import { cookies, headers } from 'next/headers'

const THEMES = ['light', 'dark'] as const

type Theme = (typeof THEMES)[number]

const DEFAULT_THEME: Theme = 'light'

function isTheme(value: string | undefined): value is Theme {
  return THEMES.includes(value as Theme)
}

/**
 * Picks the highest-priority language tag from an `Accept-Language` header,
 * e.g. `en-US,en;q=0.9,fr;q=0.8` -> `en-US`. Returns null when the header is
 * missing or only contains the `*` wildcard.
 */
function parsePreferredLanguage(acceptLanguage: string | null): string | null {
  if (!acceptLanguage) return null

  const languages = acceptLanguage
    .split(',')
    .map((part) => {
      const [tag, ...params] = part.trim().split(';')
      const qParam = params.find((param) => param.trim().startsWith('q='))
      const quality = qParam ? Number.parseFloat(qParam.trim().slice(2)) : 1
      return { tag: tag.trim(), quality: Number.isNaN(quality) ? 0 : quality }
    })
    .filter(({ tag, quality }) => tag !== '' && tag !== '*' && quality > 0)
    // Sort is stable, so equal-quality tags keep their header order.
    .sort((a, b) => b.quality - a.quality)

  return languages[0]?.tag ?? null
}

function describeLanguage(tag: string): string {
  try {
    const displayNames = new Intl.DisplayNames(['en'], { type: 'language' })
    return displayNames.of(tag) ?? tag
  } catch {
    // Malformed tag from an untrusted header — show it verbatim.
    return tag
  }
}

export default async function Preferences() {
  // `cookies()` and `headers()` are async-only as of Next.js 16.
  const [cookieStore, headersList] = await Promise.all([cookies(), headers()])

  const themeCookie = cookieStore.get('theme')?.value
  const theme = isTheme(themeCookie) ? themeCookie : DEFAULT_THEME
  const isDefaultTheme = !isTheme(themeCookie)

  const preferredLanguage = parsePreferredLanguage(
    headersList.get('accept-language')
  )

  return (
    <section>
      <h2>Theme</h2>
      <p>
        Current theme: <strong>{theme}</strong>
        {isDefaultTheme ? ' (default — no theme cookie set)' : null}
      </p>

      <h2>Language</h2>
      <p>
        {preferredLanguage ? (
          <>
            Preferred language: <strong>{describeLanguage(preferredLanguage)}</strong>{' '}
            ({preferredLanguage})
          </>
        ) : (
          'Preferred language: not specified by the browser'
        )}
      </p>
    </section>
  )
}

